import{_ as r,a0 as n,w as u,s as p,ao as s,I as a,x as t,a1 as i,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"防止文檔陷阱的 7 條準則 | LCTT x X-CMD","titleTemplate":false,"description":"防止文檔陷阱的 7 條準則 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"防止文檔陷阱的 7 條準則 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"防止文檔陷阱的 7 條準則 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20171205 7 rules for avoiding documentation pitfalls","title":"防止文檔陷阱的 7 條準則","tag":"201804","desc":""},"relativePath":"201804/20171205 7 rules for avoiding documentation pitfalls.md","filePath":"[post].md"}'),d={name:"201804/20171205 7 rules for avoiding documentation pitfalls.md"};function m(f,e,T,_,h,g){const o=n("Link");return u(),p("div",null,[e[19]||(e[19]=s('<h1 id="防止文檔陷阱的-7-條準則" tabindex="-1">防止文檔陷阱的 7 條準則 <a class="header-anchor" href="#防止文檔陷阱的-7-條準則" aria-label="Permalink to “防止文檔陷阱的 7 條準則”">​</a></h1><blockquote><p>讓我們瞭解一下如何使國外讀者更容易理解你的技術文章。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/osdc-docdish-typewriterkeys-4-series.png?itok=ccZISDxR" alt=""></p><p>英語是開源社區的通用語言。為了減少翻譯成本，很多團隊都改成用英語來寫他們的文檔。 但奇怪的是，為國際讀者寫英語並不一定就意味着以英語為母語的人就佔據更多的優勢。 相反， 他們往往忘記了該文檔用的語言可能並不是讀者的母語。</p><p>我們以下面這個簡單的句子為例： “Encrypt the password using the <code>foo bar</code> command。”語法上來説，這個句子是正確的。 鑑於動名詞的 “-ing” 形式在英語中很常見，大多數的母語人士都認為這是一種優雅的表達方式， 他們通常會很自然的寫出這樣的句子。 但是仔細觀察， 這個句子存在歧義因為 “using” 可能指的賓語（“the password”）也可能指的動詞(“encrypt”）。 因此這個句子有兩種解讀方式:</p><ul><li>“加密使用了 <code>foo bar</code> 命令的密碼。”</li><li>“使用命令 <code>foo bar</code> 來加密密碼。”</li></ul><p>如果你有相關的先驗知識（密碼加密或者 <code>foo bar</code> 命令），你可以消除這種不確定性並且明白第二種方式才是真正的意思。 但是若你沒有足夠深入的知識怎麼辦呢？ 如果你並不是這方面的專家，而只是一個擁有泛泛相關知識的翻譯者而已怎麼辦呢？ 再或者，如果你只是個非母語人士且對像動名詞這種高級語法不熟悉怎麼辦呢？</p><p>即使是英語為母語的人也需要經過訓練才能寫出清晰直接的技術文檔。訓練的第一步就是提高對文本可用性以及潛在問題的警覺性， 下面讓我們來看一下可以幫助避免常見陷阱的 7 條規則。</p><h3 id="_1、瞭解你的目標讀者並代入其中。" tabindex="-1">1、瞭解你的目標讀者並代入其中。 <a class="header-anchor" href="#_1、瞭解你的目標讀者並代入其中。" aria-label="Permalink to “1、瞭解你的目標讀者並代入其中。”">​</a></h3>',9)),a("p",null,[e[1]||(e[1]=t("如果你是一名開發者，而寫作的對象是最終用户， 那麼你需要站在他們的角度來看這個產品。 文檔的結構是否反映了用户的目標？ ",-1)),i(o,{href:"https://en.wikipedia.org/wiki/Persona_(user_experience)"},{default:l(()=>[...e[0]||(e[0]=[a("ruby",null,[t("人格面具"),a("rt",null,"persona")],-1),t(" 技術",-1)])]),_:1}),e[2]||(e[2]=t(" 能幫你專注於目標受眾併為你的讀者提供合適層次的細節。",-1))]),e[20]||(e[20]=s('<h3 id="_2、遵循-kiss-原則——保持文檔簡短而簡單" tabindex="-1">2、遵循 KISS 原則——保持文檔簡短而簡單 <a class="header-anchor" href="#_2、遵循-kiss-原則——保持文檔簡短而簡單" aria-label="Permalink to “2、遵循 KISS 原則——保持文檔簡短而簡單”">​</a></h3><p>這個原則適用於多個層次，從語法，句子到單詞。 比如:</p><ul><li>使用合適的最簡單時態。比如， 當提到一個動作的結果時使用現在時: <ul><li>&quot; <s>Click &#39;OK.&#39; The &#39;Printer Options&#39; dialog will appear.</s> &quot; -&gt; &quot;Click &#39;OK.&#39; The &#39;Printer Options&#39; dialog appears.&quot;</li></ul></li><li>按經驗來説，一個句子表達一個主題；然而， 短句子並不一定就容易理解（尤其當這些句子都是由名詞組成時）。 有時， 將句子裁剪過度可能會引起歧義，而反過來太多單詞則又難以理解。</li><li>不常用的以及很長的單詞會降低閲讀速度，而且可能成為非母語人士的障礙。 使用更簡單的替代詞語: <ul><li>&quot; <s>utilize</s> &quot; -&gt; &quot;use&quot;</li><li>&quot; <s>indicate</s> &quot; -&gt; &quot;show&quot;，&quot;tell&quot; 或 &quot;say&quot;</li><li>&quot; <s>prerequisite</s> &quot; -&gt; &quot;requirement&quot;</li></ul></li></ul><h3 id="_3、不要干擾閲讀流" tabindex="-1">3、不要干擾閲讀流 <a class="header-anchor" href="#_3、不要干擾閲讀流" aria-label="Permalink to “3、不要干擾閲讀流”">​</a></h3><p>將虛詞和較長的插入語移到句子的首部或者尾部:</p><ul><li>&quot; <s>They are not, however, marked as installed.</s> &quot; -&gt; &quot;However, they are not marked as installed.&quot;</li></ul><p>將長命令放在句子的末尾可以讓自動/半自動的翻譯擁有更好的斷句。</p><h3 id="_4、區別對待兩種基本的信息類型" tabindex="-1">4、區別對待兩種基本的信息類型 <a class="header-anchor" href="#_4、區別對待兩種基本的信息類型" aria-label="Permalink to “4、區別對待兩種基本的信息類型”">​</a></h3><p>描述型信息以及任務導向型信息有必要區分開來。描述型信息的一個典型例子就是命令列參考， 而 HOWTO 則是屬於基於任務的信息；（LCTT 譯註：HOWTO 文檔是 Linux 文檔中的一種）然而， 技術寫作中都會涉及這兩種類型的信息。 仔細觀察， 就會發現許多文本都同時包含了兩種類型的信息。 然而如果能夠清晰地劃分這兩種類型的信息那必是極好的。 為了更好地區分它們，可以對它們進行分別標記。 標題應該能夠反映章節的內容以及信息的類型。 對描述性章節使用基於名詞的標題（比如“Types of Frobnicators”），而對基於任務的章節使用口頭表達式的標題（例如“Installing Frobnicators”）。 這可以讓讀者快速定位感興趣的章節而跳過對他無用的章節。</p><h3 id="_5、考慮不同的閲讀場景和閲讀模式" tabindex="-1">5、考慮不同的閲讀場景和閲讀模式 <a class="header-anchor" href="#_5、考慮不同的閲讀場景和閲讀模式" aria-label="Permalink to “5、考慮不同的閲讀場景和閲讀模式”">​</a></h3><p>有些讀者在閲讀產品文檔時會由於自己搞不定而感到十分的沮喪。他們在一個嘈雜的環境中工作，也很難專注於閲讀。 同時，不要期望你的讀者會一頁一頁的進行閲讀，很多人都是快速瀏覽文本，搜索關鍵字或者通過表格、索引以及全文搜索的方式來查找主題。 請牢記這一點， 從不同的角度來看待你的文字。 通常需要折中才能找到一種適合多種情況的文本結構。</p><h3 id="_6、將複雜的信息分成小塊" tabindex="-1">6、將複雜的信息分成小塊 <a class="header-anchor" href="#_6、將複雜的信息分成小塊" aria-label="Permalink to “6、將複雜的信息分成小塊”">​</a></h3>',12)),a("p",null,[e[4]||(e[4]=t("這會讓讀者更容易記住和吸收信息。例如， 過程不應該超過 7 到 10 個步驟（根據認知心理學中的 ",-1)),i(o,{href:"https://en.wikipedia.org/wiki/The_Magical_Number_Seven,_Plus_or_Minus_Two"},{default:l(()=>[...e[3]||(e[3]=[t("米勒法則",-1)])]),_:1}),e[5]||(e[5]=t("）。 如果需要更多的步驟， 那麼就將任務分拆成不同的過程。",-1))]),e[21]||(e[21]=s('<h3 id="_7、形式遵循功能" tabindex="-1">7、形式遵循功能 <a class="header-anchor" href="#_7、形式遵循功能" aria-label="Permalink to “7、形式遵循功能”">​</a></h3><p>根據以下問題檢查你的文字：某句話/段落/章節的 <em>目的</em>（功能）是什麼？比如，它是一個指令呢？還是一個結果呢？還是一個警告呢？如果是指令， 使用主動語氣： “Configure the system.” 被動語氣可能適合於進行描述： “The system is configured automatically.” 將警告放在危險操作的 <em>前面</em> 。 專注於目的還有助於發現冗餘的內容，可以清除類似 “basically” 或者 “easily” 這一類的填充詞，類似 “<s>already</s> existing ” 或“ <s>completely</s> new” 這一類的不必要的修飾， 以及任何與你的目標大眾無關的內容。</p><p>你現在可能已經猜到了，寫作就是一個不斷重寫的過程。 好的寫作需要付出努力和練習。 即使你只是偶爾寫點東西， 你也可以通過關注目標大眾並遵循上述規則來顯著地改善你的文字。 文字的可讀性越好， 理解就越容易， 這一點對不同語言能力的讀者來説都是適合的。 尤其是當進行本地化時， 高質量的原始文本至關重要：“垃圾進， 垃圾出”。 如果原始文本就有缺陷， 翻譯所需要的時間就會變長， 從而導致更高的成本。 最壞的情況下， 翻譯會導致缺陷成倍增加，需要在不同的語言版本中修正這個缺陷。</p><hr>',4)),a("p",null,[e[7]||(e[7]=t("via: ",-1)),i(o,{href:"https://opensource.com/article/17/12/7-rules"},{default:l(()=>[...e[6]||(e[6]=[t("https://opensource.com/article/17/12/7-rules",-1)])]),_:1})]),a("p",null,[e[11]||(e[11]=t("作者：",-1)),i(o,{href:"https://opensource.com"},{default:l(()=>[...e[8]||(e[8]=[t("Tanja Roth",-1)])]),_:1}),e[12]||(e[12]=t(" 譯者：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[9]||(e[9]=[t("lujun9972",-1)])]),_:1}),e[13]||(e[13]=t(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:l(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),a("p",null,[e[16]||(e[16]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[14]||(e[14]=[t("LCTT",-1)])]),_:1}),e[17]||(e[17]=t(" 原創編譯，",-1)),i(o,{href:"https://linux.cn/"},{default:l(()=>[...e[15]||(e[15]=[t("Linux中國",-1)])]),_:1}),e[18]||(e[18]=t(" 榮譽推出",-1))])])}const x=r(d,[["render",m]]);export{k as __pageData,x as default};
